m=json.load(open('/tmp/ghost_candidate.json'))['diagrams'][0]['mappings']; paths=sorted({v['path'] for v in m}); print('Per-file numbered range reads for',len(paths),'files,',len(m),'ranges');
for p in paths:
    ranges=[(v['startLine'],v['endLine']) for v in m if v['path']==p]; r=subprocess.run(['nl','-ba',p],capture_output=True,text=True,check=True); lines=r.stdout.splitlines(); assert all(1<=a<=b<=len(lines) for a,b in ranges); print(p,len(lines),len(ranges), ' '.join(f'{a}-{b}' for a,b in ranges));
    for a,b in ranges: selected=lines[a-1:b]; assert selected and selected[0].strip().startswith(str(a));
